import React, { useState, useMemo, useEffect } from 'react';
import { 
  Plus, 
  Trash2, 
  FileText, 
  Download, 
  User, 
  MapPin, 
  CreditCard, 
  ShoppingBag, 
  Search, 
  MessageSquare,
  ChevronRight,
  Sparkles,
  Info
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import { GoogleGenAI } from "@google/genai";
import { INITIAL_DATA, PRODUCT_CATALOG, ReceiptData, Product } from './types';

const App: React.FC = () => {
  const [data, setData] = useState<ReceiptData>(INITIAL_DATA);
  const [searchTerm, setSearchTerm] = useState('');
  const [isGeneratingMessage, setIsGeneratingMessage] = useState(false);
  const [aiMessage, setAiMessage] = useState('');

  // Lógica de busca de produtos
  const filteredCatalog = useMemo(() => {
    if (!searchTerm) return [];
    return PRODUCT_CATALOG.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase())
    ).slice(0, 5);
  }, [searchTerm]);

  const addProduct = (catalogItem: { name: string, price: number }) => {
    const newProduct: Product = {
      name: catalogItem.name,
      price: catalogItem.price,
      quantity: 1,
      warrantyTime: '1',
      warrantyUnit: 'ANOS'
    };
    setData(prev => ({
      ...prev,
      products: [...prev.products, newProduct]
    }));
    setSearchTerm('');
  };

  const removeProduct = (index: number) => {
    setData(prev => ({
      ...prev,
      products: prev.products.filter((_, i) => i !== index)
    }));
  };

  const updateProduct = (index: number, field: keyof Product, value: any) => {
    const newProducts = [...data.products];
    newProducts[index] = { ...newProducts[index], [field]: value };
    setData(prev => ({ ...prev, products: newProducts }));
  };

  const subtotal = useMemo(() => {
    return data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  }, [data.products]);

  const total = useMemo(() => {
    let discount = 0;
    if (data.discountType === 'percentage') {
      discount = subtotal * (data.discountValue / 100);
    } else {
      discount = data.discountValue;
    }
    return Math.max(0, subtotal - discount - (data.bundleDiscount || 0));
  }, [subtotal, data.discountType, data.discountValue, data.bundleDiscount]);

  const handleGeneratePDF = () => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();

    // Header
    doc.setFillColor(30, 64, 175);
    doc.rect(0, 0, pageWidth, 40, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.text("BELCONFORT ECOSYSTEM", 15, 25);
    doc.setFontSize(10);
    doc.text("COMPROVANTE DE COMPRA OFICIAL", 15, 32);

    // Date & Code
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(10);
    doc.text(`Data: ${data.date || new Date().toLocaleDateString('pt-BR')}`, pageWidth - 15, 50, { align: 'right' });
    doc.text(`Código: ${data.saleCode || 'N/A'}`, pageWidth - 15, 55, { align: 'right' });

    // Client Info
    doc.setFont("helvetica", "bold");
    doc.text("DADOS DO CLIENTE", 15, 70);
    doc.setFont("helvetica", "normal");
    doc.text(`Nome: ${data.name}`, 15, 78);
    doc.text(`CPF: ${data.cpf}`, 15, 84);
    doc.text(`Endereço: ${data.street}, ${data.number} - ${data.neighborhood}`, 15, 90);
    doc.text(`Cidade: ${data.city} | Contato: ${data.contact1}`, 15, 96);

    // Table Header
    doc.setFillColor(240, 240, 240);
    doc.rect(15, 110, pageWidth - 30, 8, 'F');
    doc.setFont("helvetica", "bold");
    doc.text("PRODUTO", 20, 116);
    doc.text("QTD", 120, 116);
    doc.text("VALOR UN.", 145, 116);
    doc.text("TOTAL", 175, 116);

    // Table Content
    let y = 125;
    doc.setFont("helvetica", "normal");
    data.products.forEach((p) => {
      if (y > 270) {
        doc.addPage();
        y = 20;
      }
      doc.text(p.name.substring(0, 45), 20, y);
      doc.text(p.quantity.toString(), 125, y, { align: 'center' });
      doc.text(`R$ ${p.price.toFixed(2)}`, 155, y, { align: 'right' });
      doc.text(`R$ ${(p.price * p.quantity).toFixed(2)}`, 190, y, { align: 'right' });
      y += 8;
    });

    // Summary
    y += 10;
    doc.line(15, y, pageWidth - 15, y);
    y += 10;
    doc.text(`Subtotal: R$ ${subtotal.toFixed(2)}`, 190, y, { align: 'right' });
    y += 6;
    if (data.discountValue > 0) {
      const disc = data.discountType === 'percentage' ? `${data.discountValue}%` : `R$ ${data.discountValue.toFixed(2)}`;
      doc.text(`Desconto: ${disc}`, 190, y, { align: 'right' });
      y += 6;
    }
    doc.setFont("helvetica", "bold");
    doc.setFontSize(14);
    doc.text(`TOTAL: R$ ${total.toFixed(2)}`, 190, y + 5, { align: 'right' });

    // Footer
    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.text("Agradecemos a preferência pela Belconfort. Este documento é um comprovante de venda.", pageWidth / 2, 285, { align: 'center' });

    doc.save(`Comprovante_${data.name || 'Cliente'}.pdf`);
  };

  const generateAIMessage = async () => {
    if (data.products.length === 0) return;
    setIsGeneratingMessage(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Crie uma mensagem de WhatsApp profissional e elegante para o cliente ${data.name}. 
      Ele comprou: ${data.products.map(p => `${p.quantity}x ${p.name}`).join(', ')}.
      Vendedor: ${data.salesperson}.
      Total da compra: R$ ${total.toFixed(2)}.
      A empresa é a Belconfort (especialista em conforto e colchões).
      A mensagem deve ser curta, cordial, agradecer a preferência e mencionar que o comprovante foi gerado. Use emojis de forma discreta.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });

      setAiMessage(response.text || '');
    } catch (error) {
      console.error(error);
      setAiMessage("Olá! Agradecemos sua compra na Belconfort. Seu pedido já foi processado e o comprovante está disponível.");
    } finally {
      setIsGeneratingMessage(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-950 text-slate-200 font-sans p-4 md:p-8">
      <header className="max-w-7xl mx-auto mb-10 flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-gray-800 pb-8">
        <div>
          <h1 className="text-4xl font-serif font-bold text-white tracking-tight flex items-center gap-3">
            <ShoppingBag className="text-bel-blue w-10 h-10" />
            Belconfort <span className="text-bel-blue">Ecosystem</span>
          </h1>
          <p className="text-slate-400 mt-2 text-sm uppercase tracking-widest">Plataforma de Gestão e Comprovantes</p>
        </div>

        <div className="flex gap-3">
          <button 
            onClick={handleGeneratePDF}
            className="flex items-center gap-2 bg-bel-blue hover:bg-blue-700 text-white px-6 py-3 rounded-lg transition-all font-semibold shadow-lg shadow-blue-900/20 active:scale-95"
          >
            <Download size={20} />
            Gerar PDF
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Formulário */}
        <div className="lg:col-span-8 space-y-8">
          {/* Sessão Cliente */}
          <section className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
            <h2 className="text-xl font-semibold mb-6 flex items-center gap-2 text-white">
              <User size={20} className="text-bel-blue" />
              Informações do Cliente
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input 
                placeholder="Nome do Cliente"
                className="bg-gray-850 border border-gray-700 rounded-lg p-3 outline-none focus:border-bel-blue transition-colors w-full"
                value={data.name}
                onChange={e => setData({...data, name: e.target.value})}
              />
              <input 
                placeholder="CPF / CNPJ"
                className="bg-gray-850 border border-gray-700 rounded-lg p-3 outline-none focus:border-bel-blue transition-colors w-full"
                value={data.cpf}
                onChange={e => setData({...data, cpf: e.target.value})}
              />
              <div className="md:col-span-2 flex gap-4">
                <input 
                  placeholder="Endereço"
                  className="bg-gray-850 border border-gray-700 rounded-lg p-3 outline-none focus:border-bel-blue transition-colors flex-grow"
                  value={data.street}
                  onChange={e => setData({...data, street: e.target.value})}
                />
                <input 
                  placeholder="Nº"
                  className="bg-gray-850 border border-gray-700 rounded-lg p-3 outline-none focus:border-bel-blue transition-colors w-24"
                  value={data.number}
                  onChange={e => setData({...data, number: e.target.value})}
                />
              </div>
              <input 
                placeholder="Cidade"
                className="bg-gray-850 border border-gray-700 rounded-lg p-3 outline-none focus:border-bel-blue transition-colors w-full"
                value={data.city}
                onChange={e => setData({...data, city: e.target.value})}
              />
              <input 
                placeholder="Telefone"
                className="bg-gray-850 border border-gray-700 rounded-lg p-3 outline-none focus:border-bel-blue transition-colors w-full"
                value={data.contact1}
                onChange={e => setData({...data, contact1: e.target.value})}
              />
            </div>
          </section>

          {/* Adicionar Produtos */}
          <section className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
            <h2 className="text-xl font-semibold mb-6 flex items-center gap-2 text-white">
              <ShoppingBag size={20} className="text-bel-blue" />
              Seleção de Itens
            </h2>

            <div className="relative mb-6">
              <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none text-slate-500">
                <Search size={18} />
              </div>
              <input 
                placeholder="Buscar produto no catálogo..."
                className="bg-gray-850 border border-gray-700 rounded-lg pl-10 pr-4 py-3 outline-none focus:border-bel-blue transition-colors w-full"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />

              {filteredCatalog.length > 0 && (
                <div className="absolute top-full left-0 right-0 mt-2 bg-gray-850 border border-gray-700 rounded-xl overflow-hidden shadow-2xl z-50">
                  {filteredCatalog.map((item, idx) => (
                    <button
                      key={idx}
                      onClick={() => addProduct(item)}
                      className="w-full text-left p-4 hover:bg-gray-800 flex justify-between items-center transition-colors border-b border-gray-800 last:border-0"
                    >
                      <span className="font-medium">{item.name}</span>
                      <span className="text-bel-blue font-bold">R$ {item.price.toFixed(2)}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="space-y-3">
              {data.products.map((p, idx) => (
                <div key={idx} className="flex flex-col md:flex-row items-start md:items-center gap-4 bg-gray-850/50 p-4 rounded-xl border border-gray-800 group transition-all hover:border-gray-700">
                  <div className="flex-grow">
                    <p className="font-semibold text-white">{p.name}</p>
                    <p className="text-xs text-slate-500 mt-1">Preço Unitário: R$ {p.price.toFixed(2)}</p>
                  </div>
                  <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="flex items-center bg-gray-950 border border-gray-700 rounded-lg overflow-hidden">
                      <button 
                        onClick={() => updateProduct(idx, 'quantity', Math.max(1, p.quantity - 1))}
                        className="px-3 py-1 hover:bg-gray-800 text-slate-400"
                      >-</button>
                      <span className="px-3 font-bold text-white min-w-[3ch] text-center">{p.quantity}</span>
                      <button 
                        onClick={() => updateProduct(idx, 'quantity', p.quantity + 1)}
                        className="px-3 py-1 hover:bg-gray-800 text-slate-400"
                      >+</button>
                    </div>
                    <button 
                      onClick={() => removeProduct(idx)}
                      className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg transition-colors ml-auto"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                </div>
              ))}
              {data.products.length === 0 && (
                <div className="text-center py-10 text-slate-500 border-2 border-dashed border-gray-800 rounded-xl">
                  <ShoppingBag size={40} className="mx-auto mb-3 opacity-20" />
                  Nenhum produto adicionado à compra
                </div>
              )}
            </div>
          </section>
        </div>

        {/* Resumo Lateral */}
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl sticky top-8">
            <h2 className="text-xl font-semibold mb-6 text-white border-b border-gray-800 pb-4">Resumo do Pedido</h2>

            <div className="space-y-4 mb-6">
              <div className="flex justify-between text-slate-400">
                <span>Subtotal</span>
                <span>R$ {subtotal.toFixed(2)}</span>
              </div>

              <div className="flex flex-col gap-2">
                <label className="text-xs text-slate-500 uppercase font-bold">Desconto</label>
                <div className="flex gap-2">
                  <select 
                    className="bg-gray-850 border border-gray-700 rounded-lg p-2 text-sm"
                    value={data.discountType}
                    onChange={e => setData({...data, discountType: e.target.value as any})}
                  >
                    <option value="fixed">R$</option>
                    <option value="percentage">%</option>
                  </select>
                  <input 
                    type="number"
                    className="bg-gray-850 border border-gray-700 rounded-lg p-2 text-sm w-full"
                    value={data.discountValue}
                    onChange={e => setData({...data, discountValue: Number(e.target.value)})}
                  />
                </div>
              </div>

              <div className="pt-4 border-t border-gray-800">
                <div className="flex justify-between items-end">
                  <span className="text-slate-300 font-medium">Total</span>
                  <span className="text-3xl font-bold text-white">R$ {total.toFixed(2)}</span>
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <button 
                onClick={handleGeneratePDF}
                disabled={data.products.length === 0}
                className="w-full bg-bel-blue hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white py-4 rounded-xl font-bold transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2"
              >
                <FileText size={20} />
                GERAR COMPROVANTE PDF
              </button>

              <button 
                onClick={generateAIMessage}
                disabled={data.products.length === 0 || isGeneratingMessage}
                className="w-full bg-slate-800 hover:bg-slate-700 text-slate-200 py-4 rounded-xl font-bold transition-all flex items-center justify-center gap-2"
              >
                {isGeneratingMessage ? (
                  <div className="animate-spin rounded-full h-5 w-5 border-2 border-slate-400 border-t-transparent"></div>
                ) : (
                  <Sparkles size={20} className="text-yellow-500" />
                )}
                GERAR MENSAGEM COM IA
              </button>
            </div>

            {aiMessage && (
              <div className="mt-6 p-4 bg-bel-blue/10 border border-bel-blue/30 rounded-xl relative group">
                <h3 className="text-xs font-bold text-bel-blue uppercase mb-2 flex items-center gap-1">
                  <Info size={14} /> Sugestão da IA
                </h3>
                <p className="text-sm text-slate-300 leading-relaxed italic">"{aiMessage}"</p>
                <button 
                  onClick={() => navigator.clipboard.writeText(aiMessage)}
                  className="mt-3 text-xs text-bel-blue hover:underline font-bold"
                >
                  Copiar Mensagem
                </button>
              </div>
            )}
          </section>

          <div className="p-6 bg-gradient-to-br from-gray-900 to-bel-blue/10 border border-gray-800 rounded-2xl">
             <h3 className="font-bold text-white mb-2 flex items-center gap-2">
               <CreditCard size={18} className="text-bel-blue" />
               Belconfort Cloud
             </h3>
             <p className="text-xs text-slate-400 leading-relaxed">
               Todas as vendas geradas são processadas localmente para sua segurança. 
               O catálogo é atualizado semanalmente pela nossa central.
             </p>
          </div>
        </div>
      </main>

      <footer className="max-w-7xl mx-auto mt-20 pb-10 text-center text-slate-600 text-sm">
        <p>© {new Date().getFullYear()} Belconfort Indústria de Colchões. Todos os direitos reservados.</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCTS_LIST, PRODUCT_CATALOG, Product } from './types';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  Calendar, User, MapPin, Hash, Map, Building2, 
  Phone, Download, Printer, CreditCard, Plus, Trash2, Tag, Percent, Search,
  ShieldCheck, Mail, MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, Copy, RotateCcw, AlertTriangle
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';

const fuse = new Fuse(PRODUCTS_LIST, {
  includeScore: true,
  threshold: 0.4,
  ignoreLocation: true,
});

const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1,
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return { ...INITIAL_DATA, ...JSON.parse(savedData) };
      }
    } catch (error) {}
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  const [newSalespersonName, setNewSalespersonName] = useState("");
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearchTerm(searchTerm), 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [data]);

  useEffect(() => {
    localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople));
  }, [salespeople]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleResetData = () => {
    if (window.confirm("Novo atendimento? Os dados atuais serão apagados.")) {
        setData(INITIAL_DATA);
        setSearchTerm("");
        setDiscountInput("");
    }
  };

  const filteredProducts = debouncedSearchTerm
    ? fuse.search(debouncedSearchTerm).map(result => result.item)
    : PRODUCTS_LIST;

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const product = PRODUCT_CATALOG.find(p => p.name === name);
    if (product) setSelectedPrice(product.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();

    const newProduct: Product = {
      code: pseudoCode,
      name: selectedProduct,
      price: priceValue,
      quantity: quantityValue,
      warrantyTime: "",
      warrantyUnit: "MESES"
    };

    setData(prev => ({ ...prev, products: [...prev.products, newProduct] }));
    setSelectedProduct("");
    setSearchTerm("");
  };

  const handleRemoveProduct = (index: number) => {
    setData(prev => ({ ...prev, products: prev.products.filter((_, i) => i !== index) }));
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - manualDiscount);

  const handleGeneratePDF = async () => {
    await generateReceiptPDF(data);
  };

  const handleSendWhatsApp = async () => {
    const totalFormatted = totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const messageText = `Olá ${data.name || 'Cliente'}! Aqui está seu comprovante BelConfort.\nValor Total: ${totalFormatted}\nAtendido por: ${data.salesperson}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(messageText)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50 p-4">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-serif font-bold text-white">BelConfort</h1>
          <span className="text-xs font-medium px-2 py-1 bg-white/10 rounded-full text-white">v1.6.0</span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-5 space-y-6">
          <div className="flex p-1 space-x-1 bg-gray-900 rounded-xl border border-gray-800">
            <button onClick={() => setActiveTab('manual')} className={`flex-1 py-2 rounded-lg text-sm ${activeTab === 'manual' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>Manual</button>
            <button onClick={() => setActiveTab('import')} className={`flex-1 py-2 rounded-lg text-sm ${activeTab === 'import' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>Importar</button>
          </div>

          {activeTab === 'manual' && (
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl space-y-4">
              <div className="relative">
                <Input label="Buscar Produto..." value={searchTerm} onChange={(e) => { setSearchTerm(e.target.value); setIsSearchOpen(true); }} onFocus={() => setIsSearchOpen(true)} icon={<Search className="w-4 h-4" />} />
                {isSearchOpen && (
                  <div className="absolute z-20 w-full mt-1 bg-gray-800 border border-gray-700 rounded-lg shadow-xl max-h-40 overflow-y-auto">
                    {filteredProducts.map((product) => (
                      <button key={product} className="w-full text-left px-4 py-2 text-sm text-gray-200 hover:bg-gray-700 border-b border-gray-700 last:border-0" onClick={() => handleSearchSelect(product)}>{product}</button>
                    ))}
                  </div>
                )}
              </div>
              <div className="grid grid-cols-2 gap-2">
                <Input label="Qtd" type="number" value={selectedQuantity} onChange={(e) => setSelectedQuantity(e.target.value)} />
                <Input label="Valor" type="text" value={selectedPrice} readOnly />
              </div>
              <button onClick={handleAddProduct} className="w-full bg-blue-600 hover:bg-blue-700 py-3 rounded-lg font-bold">ADICIONAR</button>

              <div className="space-y-2">
                {data.products.map((p, idx) => (
                  <div key={idx} className="flex justify-between items-center bg-gray-800 p-3 rounded-lg">
                    <span className="text-sm truncate pr-2">{p.quantity}x {p.name}</span>
                    <button onClick={() => handleRemoveProduct(idx)} className="text-red-400"><Trash2 size={16}/></button>
                  </div>
