        <div className="lg:col-span-7">
          <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 space-y-4 shadow-2xl">
            <div className="flex justify-between gap-2">
              <button onClick={handleResetData} className="flex-1 bg-red-600 p-2 rounded text-sm">Novo</button>
              <button onClick={handleSendWhatsApp} className="flex-1 bg-green-600 p-2 rounded text-sm">WhatsApp</button>
              <button onClick={handleGeneratePDF} className="flex-1 bg-blue-600 p-2 rounded text-sm">PDF</button>
