            <div className="bg-white text-gray-900 p-6 rounded shadow-inner min-h-[400px]">
              <h2 className="text-center font-bold text-lg mb-4">PREVIEW DO COMPROVANTE</h2>
              <div className="space-y-2 text-xs">
                <p><strong>Cliente:</strong> {data.name || '---'}</p>
                <p><strong>Vendedor:</strong> {data.salesperson || '---'}</p>
                <div className="border-t border-gray-200 pt-2">
                  {data.products.map((p, i) => (
                    <div key={i} className="flex justify-between">
                      <span>{p.quantity}x {p.name}</span>
                      <span>{(p.price * p.quantity).toFixed(2)}</span>
                    </div>
                  ))}
                </div>
                <p className="text-right font-bold text-sm pt-4">TOTAL: R$ {totalValue.toFixed(2)}</p>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

