export const generateClientMessage = async (data: ReceiptData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const totalText = subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const prompt = `Você é um assistente da BelConfort. Escreva uma mensagem curta de WhatsApp agradecendo a compra de ${data.name}. Itens: ${data.products.map(p => p.name).join(', ')}. Total: ${totalText}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Obrigado por comprar na BelConfort!";
  } catch (error) {
    console.error("AI Error:", error);
    return "Obrigado pela preferência!";
  }
};

export const parseReceiptFromText = async (text: string, catalogNames: string[] = []): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `Analise este texto de pedido e extraia dados do cliente e produtos: ${text}. Produtos disponíveis: ${catalogNames.join(', ')}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            clientData: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                cpf: { type: Type.STRING },
              },
              required: ["name"]
            },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  quantity: { type: Type.NUMBER }
                },
                required: ["name", "quantity"]
              }
            }
          },
          required: ["clientData", "items"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error) {
    throw new Error("Falha ao processar texto com IA");
  }
};

