import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptData } from "../types";

// Always initialize GoogleGenAI with process.env.API_KEY as per guidelines.
export const generateClientMessage = async (data: ReceiptData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  // Using gemini-3-flash-preview for basic text tasks.
  const model = "gemini-3-flash-preview";

  // Calculations for prompt
  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  let discountAmount = 0;
  if (data.discountType === 'fixed') {
    discountAmount = data.discountValue;
  } else {
    discountAmount = subtotal * (data.discountValue / 100);
  }
  const finalTotal = Math.max(0, subtotal - discountAmount);

  // Format product list for the prompt
  const productsListText = data.products.length > 0 
    ? data.products.map(p => `- ${p.quantity}x ${p.name} (${(p.price * p.quantity).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })})`).join('\n')
    : "Não especificado";

  const discountText = discountAmount > 0 
    ? `Desconto: - ${discountAmount.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}\n` 
    : '';

  const totalText = finalTotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const prompt = `
    Você é um assistente de vendas da BelConfort (Loja de Camas e Móveis).
    Escreva uma mensagem curta, amigável e profissional para o WhatsApp do cliente confirmando o pedido.

    Dados do cliente:
    Nome: ${data.name}
    CPF: ${data.cpf}
    Data: ${data.date}
    Endereço: ${data.street}, ${data.number}, ${data.neighborhood}, ${data.city} ${data.complement ? `(${data.complement})` : ''}
    Forma de Pagamento: ${data.paymentMethod}

    Produtos:
    ${productsListText}

    ${discountText}
    Valor Total: ${totalText}

    A mensagem deve agradecer a preferência pela BelConfort.
    Use emojis relacionados a conforto, móveis e casa. 
    Seja objetivo e cordial.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
    });

    return response.text || "Não foi possível gerar a mensagem.";
  } catch (error: any) {
    console.error("Error generating message:", error);
    return `Erro na IA: ${error.message || 'Desconhecido'}`;
  }
};

export const parseReceiptFromText = async (text: string, catalogNames: string[] = []): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  // Using gemini-3-flash-preview for complex parsing and text tasks.
  const model = "gemini-3-flash-preview";

  const catalogString = catalogNames.join(", ");

  const prompt = `
    Analise o seguinte texto de um pedido/ficha de cliente.

    1. Extraia os dados pessoais do cliente.
    2. Tente identificar um CÓDIGO DA VENDA, Número do Pedido ou ID (ex: #1234, 8402, PED-01).
    3. Identifique o CPF ou CNPJ do cliente se houver.
    4. Identifique os produtos mencionados que correspondam à lista de catálogos fornecida abaixo.

    REGRAS IMPORTANTES PARA PRODUTOS:
    - Analise com MUITA atenção a QUANTIDADE de cada item mencionado (ex: "2 camas" = quantidade 2, "3x travesseiros" = quantidade 3). Se não especificar, assuma 1.
    - Se o texto mencionar "TRAVESSEIRO DE BRINDE", "GANHOU TRAVESSEIRO", "TRAVESSEIRO GRÁTIS" ou qualquer menção a brinde de travesseiro, você DEVE mapear automaticamente para o produto: "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO".
    - Procure corresponder o texto do usuário com o NOME EXATO DA LISTA abaixo.

    LISTA DE PRODUTOS DO SISTEMA:
    [${catalogString}]

    Retorne um JSON com os dados do cliente e um array de itens.
    Cada item deve ter "name" (string exata da lista) e "quantity" (numero).

    Texto para analise:
    ${text}
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            clientData: {
              type: Type.OBJECT,
              properties: {
                saleCode: { type: Type.STRING },
                name: { type: Type.STRING },
                cpf: { type: Type.STRING },
                date: { type: Type.STRING },
                email: { type: Type.STRING },
                street: { type: Type.STRING },
                number: { type: Type.STRING },
                neighborhood: { type: Type.STRING },
                city: { type: Type.STRING },
                complement: { type: Type.STRING },
                contact1: { type: Type.STRING },
                contact2: { type: Type.STRING },
                paymentMethod: { type: Type.STRING },
              }
            },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  quantity: { type: Type.NUMBER }
                }
              },
            }
          }
        }
      }
    });

    // Directly access the text property as per guidelines.
    const jsonText = response.text;
    if (!jsonText) throw new Error("A IA retornou uma resposta vazia.");

    const parsedData = JSON.parse(jsonText);
    return parsedData;
  } catch (error: any) {
    console.error("Error parsing receipt text:", error);
    throw new Error(error.message || "Falha na comunicação com a IA");
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Calendar, User, MapPin, Hash, Map, Building2, 
  Phone, Download, Printer, CreditCard, Plus, Trash2, Tag, Percent, Search,
  ShieldCheck, Mail, MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, Copy, RotateCcw, AlertTriangle,
  ShoppingBag, ChevronRight, Info
} from 'lucide-react';
import { INITIAL_DATA, ReceiptData, PRODUCTS_LIST, PRODUCT_CATALOG, Product } from './types';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';

const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1,
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return { ...INITIAL_DATA, ...JSON.parse(savedData) };
      }
    } catch (error) {}
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA', 'LUANA'];
  });

  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");
  const [aiMessage, setAiMessage] = useState('');
  const [isGeneratingMessage, setIsGeneratingMessage] = useState(false);

  const fuse = useMemo(() => new Fuse(PRODUCTS_LIST, {
    includeScore: true,
    threshold: 0.4,
    ignoreLocation: true,
  }), []);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearchTerm(searchTerm), 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [data]);

  useEffect(() => {
    localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople));
  }, [salespeople]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleResetData = () => {
    if (window.confirm("Novo atendimento? Os dados atuais serão apagados.")) {
        setData(INITIAL_DATA);
        setSearchTerm("");
        setDiscountInput("");
        setAiMessage('');
    }
  };

  const filteredProducts = useMemo(() => 
    debouncedSearchTerm ? fuse.search(debouncedSearchTerm).map(result => result.item) : PRODUCTS_LIST.slice(0, 10)
  , [debouncedSearchTerm, fuse]);

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const product = PRODUCT_CATALOG.find(p => p.name === name);
    if (product) setSelectedPrice(product.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();

    const newProduct: Product = {
      code: pseudoCode,
      name: selectedProduct,
      price: priceValue,
      quantity: quantityValue,
      warrantyTime: "1",
      warrantyUnit: "ANOS"
    };

    setData(prev => ({ ...prev, products: [...prev.products, newProduct] }));
    setSelectedProduct("");
    setSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const handleRemoveProduct = (index: number) => {
    setData(prev => ({ ...prev, products: prev.products.filter((_, i) => i !== index) }));
  };

  const subtotal = useMemo(() => 
    data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0)
  , [data.products]);

  const totalValue = useMemo(() => {
    const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
    return Math.max(0, subtotal - manualDiscount);
  }, [subtotal, data.discountType, data.discountValue]);

  const handleGeneratePDF = async () => {
    if (data.products.length === 0) return alert("Adicione pelo menos um produto.");
    await generateReceiptPDF(data);
  };

  const handleSendWhatsApp = async () => {
    setIsGeneratingMessage(true);
    try {
      const msg = await generateClientMessage(data);
      setAiMessage(msg);
      window.open(`https://wa.me/${data.contact1.replace(/\D/g, '')}?text=${encodeURIComponent(msg)}`, '_blank');
    } catch (error) {
      console.error(error);
      const totalFormatted = totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
      const fallbackMsg = `Olá ${data.name || 'Cliente'}! Aqui está seu comprovante BelConfort.\nValor Total: ${totalFormatted}\nAtendido por: ${data.salesperson}`;
      window.open(`https://wa.me/${data.contact1.replace(/\D/g, '')}?text=${encodeURIComponent(fallbackMsg)}`, '_blank');
    } finally {
      setIsGeneratingMessage(false);
    }
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    setImportError(null);
    try {
      const result = await parseReceiptFromText(importText, PRODUCTS_LIST);
      setData(prev => ({
        ...prev,
        ...result.clientData,
        products: result.items.map((item: any) => {
          const catalogItem = PRODUCT_CATALOG.find(p => p.name === item.name);
          return {
            code: Math.floor(100000 + Math.random() * 900000).toString(),
            name: item.name,
            price: catalogItem?.price || 0,
            quantity: item.quantity,
            warrantyTime: "1",
            warrantyUnit: "ANOS"
          };
        })
      }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      setImportError({ title: "Erro na Importação", msg: error.message });
    } finally {
      setIsImporting(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50 px-4 py-4 md:px-8">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex flex-col">
            <h1 className="text-2xl md:text-3xl font-serif font-bold text-white tracking-tight">BelConfort</h1>
            <span className="text-[10px] text-blue-200 tracking-widest uppercase font-semibold">Camas e Móveis</span>
          </div>
          <div className="flex items-center gap-3">
             <span className="hidden sm:inline-block text-[10px] font-bold text-blue-100 uppercase tracking-tighter bg-white/10 px-2 py-1 rounded">Ecosistema Gestão</span>
             <span className="text-[10px] font-medium px-2 py-1 bg-white/10 rounded-full text-white border border-white/20">v1.6.2</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Coluna de Entrada */}
