import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types';
import QRCode from 'qrcode';
import JsBarcode from 'jsbarcode';

// Colors Palette
const COLORS = {
  brandBlue: '#1e40af',
  textDark: '#1f2937', 
  textGray: '#6b7280', 
  borderGray: '#d1d5db', 
  bgLight: '#f9fafb', 
  white: '#ffffff',
  red: '#ef4444',
  blue: '#3b82f6', 
  obsBg: '#fefce8', 
  obsBorder: '#fef9c3', 
  obsTitle: '#a16207', 
  obsText: '#374151', 
  stampBlue: '#1e3a8a', 
};

export const createPDFDoc = async (data: ReceiptData): Promise<jsPDF> => {
  const doc = new jsPDF();
  const margin = 10;
  const pageWidth = 210;
  const contentWidth = pageWidth - (margin * 2);
  const pageHeight = 297;
  let y = 10;

  const checkPageBreak = (heightNeeded: number) => {
    if (y + heightNeeded > pageHeight - margin) {
      doc.addPage();
      y = margin + 10;
      return true;
    }
    return false;
  };

  const headerHeight = 40;
  doc.setFillColor(COLORS.brandBlue);
  doc.rect(0, 0, pageWidth, headerHeight, 'F');
  doc.setTextColor(COLORS.white);
  doc.setFont("times", "bold");
  doc.setFontSize(26);
  doc.text("BelConfort", margin, 20);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.text("CAMAS E MÓVEIS", margin, 26, { charSpace: 1.5 });

  const qrSize = 25;
  const qrX = pageWidth - margin - qrSize;
  const infoX = qrX - 5; 

  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  doc.text("CNPJ 60.190.028/0001-60", infoX, 15, { align: "right" });
  doc.setFont("helvetica", "normal");
  doc.text("RUA B, 103C, CASTANHEIRA - BELEM/PA", infoX, 20, { align: "right" });
  doc.text("belconfortcamasemoveis@gmail.com", infoX, 25, { align: "right" });
  doc.text("(91) 99381-2592", infoX, 30, { align: "right" });

  try {
    const qrDataUrl = await QRCode.toDataURL('https://www.instagram.com/belconfortcamasemoveis/', {
        margin: 0,
        color: { dark: '#ffffff', light: '#1e40af' }
    });
    doc.addImage(qrDataUrl, 'PNG', qrX, 7, qrSize, qrSize);
  } catch (err) {}

  y = 48;
  doc.setTextColor(COLORS.textDark);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(14);
  doc.text("COMPROVANTE DE COMPRA", pageWidth / 2, y, { align: "center" });

  y += 5;
  doc.setFontSize(8);
  doc.setTextColor(COLORS.textGray);
  doc.setFont("helvetica", "normal");
  const dateStr = new Date().toLocaleDateString('pt-BR');
  doc.text(`Emissão: ${dateStr}`, pageWidth / 2, y, { align: "center" });

  y += 10;
  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.text("DADOS DO CLIENTE", margin, y);
  y += 6;
  doc.setFont("helvetica", "normal");
  doc.text(`NOME: ${data.name || '---'}`, margin, y);
  y += 5;
  doc.text(`CPF/CNPJ: ${data.cpf || '---'} | CONTATO: ${data.contact1 || '---'}`, margin, y);
  y += 5;
  doc.text(`ENDEREÇO: ${data.street || '---'}`, margin, y);

  y += 10;
  doc.setFillColor(COLORS.bgLight);
  doc.rect(margin, y, contentWidth, 8, 'F');
  doc.setFont("helvetica", "bold");
  doc.text("DESCRIÇÃO", margin + 2, y + 5.5);
  doc.text("QTD", margin + 120, y + 5.5);
  doc.text("TOTAL", margin + 160, y + 5.5);

  y += 8;
  doc.setFont("helvetica", "normal");
  data.products.forEach(p => {
    checkPageBreak(8);
    doc.text(p.name.substring(0, 60), margin + 2, y + 5);
    doc.text(p.quantity.toString(), margin + 125, y + 5, { align: 'center' });
    doc.text((p.price * p.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 }), margin + contentWidth - 2, y + 5, { align: 'right' });
    y += 8;
  });

  y += 10;
  doc.setLineWidth(0.5);
  doc.line(margin, y, margin + contentWidth, y);
  y += 8;
  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const total = Math.max(0, subtotal - manualDiscount);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(12);
  doc.text(`VALOR TOTAL: ${total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`, margin + contentWidth, y, { align: 'right' });

  return doc;
};

export const generateReceiptPDF = async (data: ReceiptData) => {
  const doc = await createPDFDoc(data);
  const safeName = data.name ? data.name.toUpperCase() : 'CLIENTE';
  doc.save(`COMPROVANTE - ${safeName}.pdf`);
};

export const getReceiptBlob = async (data: ReceiptData): Promise<Blob> => {
  const doc = await createPDFDoc(data);
  return doc.output('blob');
};

import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptData } from "../types";

export const generateClientMessage = async (data: ReceiptData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const finalTotal = Math.max(0, subtotal - manualDiscount);
  const totalText = finalTotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const prompt = `Você é um assistente da BelConfort. Escreva uma mensagem curta de WhatsApp agradecendo a compra de ${data.name}. 
  Ele comprou: ${data.products.map(p => `${p.quantity}x ${p.name}`).join(', ')}. 
  Total: ${totalText}. 
  Seja cordial, use emojis de casa e conforto. Mencione o vendedor ${data.salesperson}.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Obrigado por comprar na BelConfort!";
  } catch (error) {
    console.error("AI Error:", error);
    return "Obrigado pela preferência!";
  }
};

export const parseReceiptFromText = async (text: string, catalogNames: string[] = []): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const catalogStr = catalogNames.join(", ");
  const prompt = `Analise este texto de pedido e extraia dados do cliente e produtos: ${text}. 
  Produtos no catálogo: ${catalogStr}.
  Retorne EXATAMENTE os nomes do catálogo fornecido.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            clientData: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                cpf: { type: Type.STRING },
                street: { type: Type.STRING },
                contact1: { type: Type.STRING },
                saleCode: { type: Type.STRING }
              },
              required: ["name"]
            },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  quantity: { type: Type.NUMBER }
                },
                required: ["name", "quantity"]
              }
            }
          },
          required: ["clientData", "items"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error) {
    console.error(error);
    throw new Error("Falha ao processar texto com IA");
  }
};

