  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");
  const [aiMessage, setAiMessage] = useState('');
  const [isGeneratingMessage, setIsGeneratingMessage] = useState(false);

  const fuse = useMemo(() => new Fuse(PRODUCTS_LIST, {
    includeScore: true,
    threshold: 0.4,
    ignoreLocation: true,
  }), []);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearchTerm(searchTerm), 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [data]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const product = PRODUCT_CATALOG.find(p => p.name === name);
    if (product) setSelectedPrice(product.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();

    const newProduct: Product = {
      code: pseudoCode,
      name: selectedProduct,
      price: priceValue,
      quantity: quantityValue,
      warrantyTime: "1",
      warrantyUnit: "ANOS"
    };

    setData(prev => ({ ...prev, products: [...prev.products, newProduct] }));
    setSelectedProduct("");
    setSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const updateProductWarranty = (index: number, field: 'time' | 'unit', value: string) => {
    const updated = [...data.products];
    if (field === 'time') updated[index].warrantyTime = value;
    else updated[index].warrantyUnit = value as any;
    setData({ ...data, products: updated });
  };

  const subtotal = useMemo(() => 
    data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0)
  , [data.products]);

  const totalValue = useMemo(() => {
    const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
    return Math.max(0, subtotal - manualDiscount);
  }, [subtotal, data.discountType, data.discountValue]);

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans pb-20 selection:bg-blue-500">
