import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types';
import QRCode from 'qrcode';

const COLORS = {
  brandBlue: '#1e40af',
  textDark: '#1f2937', 
  textGray: '#6b7280', 
  borderGray: '#d1d5db', 
  bgLight: '#f9fafb', 
  white: '#ffffff',
};

export const createPDFDoc = async (data: ReceiptData): Promise<jsPDF> => {
  const doc = new jsPDF();
  const margin = 10;
  const pageWidth = 210;
  const contentWidth = pageWidth - (margin * 2);
  let y = 10;

  // Header Blue
  doc.setFillColor(COLORS.brandBlue);
  doc.rect(0, 0, pageWidth, 40, 'F');
  doc.setTextColor(COLORS.white);
  doc.setFont("times", "bold");
  doc.setFontSize(26);
  doc.text("BelConfort", margin, 20);
  doc.setFontSize(8);
  doc.text("CAMAS E MÓVEIS", margin, 26, { charSpace: 1.5 });

  doc.setFontSize(9);
  doc.text("CNPJ 60.190.028/0001-60", pageWidth - margin, 15, { align: "right" });
  doc.text("RUA B, 103C, CASTANHEIRA - BELEM/PA", pageWidth - margin, 20, { align: "right" });
  doc.text("(91) 99381-2592", pageWidth - margin, 25, { align: "right" });

  y = 50;
  doc.setTextColor(COLORS.textDark);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(14);
  doc.text("COMPROVANTE DE COMPRA", pageWidth / 2, y, { align: "center" });

  y += 5;
  doc.setFontSize(8);
  doc.setTextColor(COLORS.textGray);
  doc.setFont("helvetica", "normal");
  doc.text(`Emissão: ${new Date().toLocaleDateString()} | CÓD: ${data.saleCode || '---'}`, pageWidth / 2, y, { align: "center" });

  y += 10;
  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.text("DADOS DO CLIENTE", margin, y);
  y += 6;
  doc.setFont("helvetica", "normal");
  doc.text(`NOME: ${data.name || '---'}`, margin, y);
  y += 5;
  doc.text(`CPF: ${data.cpf || '---'} | CONTATO: ${data.contact1 || '---'}`, margin, y);
  y += 5;
  doc.text(`ENDEREÇO: ${data.street || '---'}, ${data.number} - ${data.neighborhood}`, margin, y);

  y += 10;
  doc.setFillColor(COLORS.bgLight);
  doc.rect(margin, y, contentWidth, 8, 'F');
  doc.setFont("helvetica", "bold");
  doc.setTextColor(COLORS.brandBlue);
  doc.text("DESCRIÇÃO", margin + 2, y + 5.5);
  doc.text("QTD", margin + 120, y + 5.5);
  doc.text("TOTAL", margin + 160, y + 5.5);

  y += 8;
  doc.setFont("helvetica", "normal");
  doc.setTextColor(COLORS.textDark);
  data.products.forEach(p => {
    const total = p.price * p.quantity;
    doc.setFont("helvetica", "bold");
    doc.text(p.name.substring(0, 60), margin + 2, y + 5);
    doc.text(p.quantity.toString(), margin + 125, y + 5, { align: 'center' });
    doc.text(total.toFixed(2), margin + contentWidth - 2, y + 5, { align: 'right' });

    if (p.warrantyTime) {
      y += 4;
      doc.setFont("helvetica", "italic");
      doc.setFontSize(7);
      doc.setTextColor(COLORS.brandBlue);
      doc.text(`GARANTIA DE FÁBRICA: ${p.warrantyTime} ${p.warrantyUnit}`, margin + 2, y + 5);
      doc.setTextColor(COLORS.textDark);
      doc.setFontSize(9);
    }
    y += 8;
  });

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const finalTotal = Math.max(0, subtotal - manualDiscount);

  y += 10;
  doc.setDrawColor(COLORS.borderGray);
  doc.line(margin, y, pageWidth - margin, y);
  y += 10;
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text(`TOTAL FINAL: R$ ${finalTotal.toFixed(2)}`, pageWidth - margin, y, { align: 'right' });

  doc.save(`COMPROVANTE_${data.name || 'CLIENTE'}.pdf`);
  return doc;
};

export const generateReceiptPDF = async (data: ReceiptData) => {
  await createPDFDoc(data);
};

export const getReceiptBlob = async (data: ReceiptData): Promise<Blob> => {
  const doc = await createPDFDoc(data);
  return doc.output('blob');
};

