import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types';

export const generateReceiptPDF = async (data: ReceiptData) => {
  const doc = new jsPDF();
  const margin = 15;
  const pageWidth = 210;
  let y = 15;

  // Header Blue
  doc.setFillColor(30, 64, 175);
  doc.rect(0, 0, pageWidth, 40, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFont("times", "bold");
  doc.setFontSize(28);
  doc.text("BelConfort", margin, 22);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.text("CAMAS E MÓVEIS", margin, 28, { charSpace: 1.5 });

  doc.setFontSize(9);
  doc.text("CNPJ 60.190.028/0001-60", pageWidth - margin, 18, { align: "right" });
  doc.text("RUA B, 103C, CASTANHEIRA - BELEM/PA", pageWidth - margin, 23, { align: "right" });
  doc.text("(91) 99381-2592", pageWidth - margin, 28, { align: "right" });

  y = 55;
  doc.setTextColor(30, 64, 175);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(14);
  doc.text("COMPROVANTE DE COMPRA", pageWidth / 2, y, { align: "center" });

  y += 5;
  doc.setFontSize(8);
  doc.setTextColor(150, 150, 150);
  doc.text(`Emissão: ${new Date().toLocaleDateString()} | CÓD: ${data.saleCode || '---'}`, pageWidth / 2, y, { align: "center" });

  y += 10;
  doc.setTextColor(0, 0, 0);
  doc.setFontSize(10);
  doc.setFont("helvetica", "bold");
  doc.setFillColor(245, 245, 245);
  doc.rect(margin, y, pageWidth - 2 * margin, 35, 'F');
  doc.rect(margin, y, pageWidth - 2 * margin, 35, 'S');

  doc.text(`CLIENTE: ${data.name || '---'}`, margin + 5, y + 8);
  doc.text(`CPF/CNPJ: ${data.cpf || '---'}`, margin + 5, y + 16);
  doc.text(`ENDEREÇO: ${data.street || '---'}, ${data.number} - ${data.neighborhood}`, margin + 5, y + 24);
  doc.text(`VENDEDOR: ${data.salesperson || '---'} | PAGAMENTO: ${data.paymentMethod || '---'}`, margin + 5, y + 32);

  y += 45;
  doc.setFillColor(30, 64, 175);
  doc.rect(margin, y, pageWidth - 2 * margin, 8, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(8);
  doc.text("DESCRIÇÃO", margin + 2, y + 5.5);
  doc.text("QTD", margin + 120, y + 5.5);
  doc.text("TOTAL", margin + 160, y + 5.5);

  y += 8;
  doc.setTextColor(0, 0, 0);
  doc.setFont("helvetica", "normal");
  data.products.forEach(p => {
    doc.setFont("helvetica", "bold");
    doc.text(p.name, margin + 2, y + 5);
    doc.text(p.quantity.toString(), margin + 122, y + 5, { align: 'center' });
    doc.text((p.price * p.quantity).toFixed(2), pageWidth - margin - 2, y + 5, { align: 'right' });

    if (p.warrantyTime) {
      y += 4;
      doc.setFont("helvetica", "italic");
      doc.setFontSize(7);
      doc.setTextColor(30, 64, 175);
      doc.text(`GARANTIA: ${p.warrantyTime} ${p.warrantyUnit} | 90 DIAS LOJA`, margin + 2, y + 5);
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(8);
    }
    y += 8;
  });

  const sub = data.products.reduce((acc, p) => acc + (p.price * p.quantity), 0);
  const disc = data.discountType === 'fixed' ? data.discountValue : sub * (data.discountValue / 100);
  const total = Math.max(0, sub - disc);

  y += 10;
  doc.setDrawColor(200, 200, 200);
  doc.line(margin, y, pageWidth - margin, y);
  y += 10;
  doc.setFontSize(14);
  doc.setFont("times", "bold");
  doc.setTextColor(30, 64, 175);
  doc.text(`TOTAL FINAL: R$ ${total.toFixed(2)}`, pageWidth - margin, y, { align: 'right' });

  doc.save(`BELCONFORT_${data.name || 'CLIENTE'}.pdf`);
};

