                <p className="text-[8px] tracking-[0.2em] font-bold">CAMAS E MÓVEIS</p>
              </div>
              <div className="text-right text-[8px] space-y-0.5 opacity-90">
                <p className="font-bold text-[9px]">60.190.028/0001-60</p>
                <p>RUA B, 103C, CASTANHEIRA - BELEM/PA</p>
                <p>(91) 99381-2592</p>
              </div>
            </div>

            <div className="text-center mb-6">
              <h2 className="text-base font-bold text-blue-900 border-b-2 border-blue-900 inline-block px-6 pb-0.5 uppercase">COMPROVANTE DE COMPRA</h2>
              <p className="text-[9px] text-gray-400 mt-2">Emissão: {new Date().toLocaleDateString()} | CÓD: {data.saleCode || '---'}</p>
            </div>

            <div className="border border-gray-300 mb-6 text-[10px]">
              <div className="grid grid-cols-[30%_1fr] border-b border-gray-300">
                <div className="p-1.5 border-r border-gray-300 bg-gray-50 uppercase font-bold text-[8px] text-gray-400">Cliente</div>
                <div className="p-1.5 font-bold uppercase">{data.name || '---'}</div>
              </div>
              <div className="grid grid-cols-[30%_1fr] border-b border-gray-300">
                <div className="p-1.5 border-r border-gray-300 bg-gray-50 uppercase font-bold text-[8px] text-gray-400">CPF/CNPJ</div>
                <div className="p-1.5">{data.cpf || '---'}</div>
              </div>
              <div className="grid grid-cols-[30%_1fr] border-b border-gray-300">
                <div className="p-1.5 border-r border-gray-300 bg-gray-50 uppercase font-bold text-[8px] text-gray-400">Endereço</div>
                <div className="p-1.5 uppercase">{data.street || '---'}, {data.number} - {data.neighborhood}</div>
              </div>
              <div className="grid grid-cols-2">
                <div className="grid grid-cols-2 border-r border-gray-300">
                  <div className="p-1.5 border-r border-gray-300 bg-gray-50 uppercase font-bold text-[8px] text-gray-400">Vendedor</div>
                  <div className="p-1.5 font-bold">{data.salesperson || '---'}</div>
                </div>
                <div className="grid grid-cols-2">
                  <div className="p-1.5 border-r border-gray-300 bg-gray-50 uppercase font-bold text-[8px] text-gray-400">Pagamento</div>
                  <div className="p-1.5 font-bold">{data.paymentMethod || '---'}</div>
                </div>
              </div>
            </div>

            <table className="w-full text-[10px] mb-auto">
              <thead>
                <tr className="bg-blue-900 text-white text-[8px]">
                  <th className="p-1.5 text-left w-12">CÓD</th>
                  <th className="p-1.5 text-left">DESCRIÇÃO</th>
                  <th className="p-1.5 text-center w-10">QTD</th>
                  <th className="p-1.5 text-right w-20">TOTAL</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {data.products.map((p, i) => (
                  <tr key={i}>
                    <td className="p-1.5 font-mono text-gray-400">#{p.code}</td>
                    <td className="p-1.5">
                      <p className="font-bold uppercase">{p.name}</p>
                      {p.warrantyTime && <p className="text-[7px] text-blue-600 font-bold italic">GARANTIA: {p.warrantyTime} {p.warrantyUnit} | 90 DIAS LOJA</p>}
                      {p.code && <BarcodePreview code={p.code}/>}
                    </td>
                    <td className="p-1.5 text-center font-bold">{p.quantity}</td>
                    <td className="p-1.5 text-right font-bold">R$ {(p.price * p.quantity).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="mt-10 border-t-2 border-gray-100 pt-6">
              <div className="flex justify-between items-end">
                <div className="space-y-4">
                  <div className="w-36 h-14 border-2 border-blue-900 rounded flex flex-col items-center justify-center text-blue-900 opacity-60 scale-75 origin-left">
                    <p className="text-[8px] font-bold">60.190.028/0001-60</p>
                    <p className="text-[6px] font-bold text-center">BELCONFORT CAMAS E MÓVEIS</p>
                  </div>
                  <div className="text-center w-48 border-t border-dashed border-gray-400 pt-1">
                    <p className="text-[8px] text-gray-400">Assinatura do Responsável</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-[9px] font-bold text-gray-400 uppercase">Total Final</p>
                  <p className="text-4xl font-serif font-bold text-blue-900 leading-none">
                    {totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
